// ═══ SOLUTION: shared flag + wait/notify ═══
class AlternatePrinter {
    private boolean numberTurn = true;  // numbers go first!
    private final Object lock = new Object();

    void printNumbers(int count) {
        for (int i = 1; i <= count; i++) {
            synchronized (lock) {
                while (!numberTurn) {         // not my turn? WAIT!
                    try { lock.wait(); } catch (InterruptedException e) { return; }
                }
                System.out.print(i + ",");
                numberTurn = false;            // letter's turn now!
                lock.notify();                 // wake the letter thread!
            }
        }
    }

    void printLetters(int count) {
        for (int i = 0; i < count; i++) {
            synchronized (lock) {
                while (numberTurn) {           // not my turn? WAIT!
                    try { lock.wait(); } catch (InterruptedException e) { return; }
                }
                System.out.print((char)('A' + i) + ",");
                numberTurn = true;             // number's turn now!
                lock.notify();                 // wake the number thread!
            }
        }
    }
}
// Output: 1,A,2,B,3,C,4,D,5,E,...
