package com.bank.alternate;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class AlternatePrintTest {

    static class AlternatePrinter {
        private boolean numberTurn = true;
        private final Object lock = new Object();
        private final List<String> output = new CopyOnWriteArrayList<>();

        void printNumbers(int count) {
            for (int i = 1; i <= count; i++) {
                synchronized (lock) {
                    while (!numberTurn) {
                        try { lock.wait(); } catch (InterruptedException e) { return; }
                    }
                    output.add(String.valueOf(i));
                    numberTurn = false;
                    lock.notify();
                }
            }
        }

        void printLetters(int count) {
            for (int i = 0; i < count; i++) {
                synchronized (lock) {
                    while (numberTurn) {
                        try { lock.wait(); } catch (InterruptedException e) { return; }
                    }
                    output.add(String.valueOf((char) ('A' + i)));
                    numberTurn = true;
                    lock.notify();
                }
            }
        }

        List<String> getOutput() { return output; }
    }

    @Test
    void alternateNumbersAndLetters() throws InterruptedException {
        AlternatePrinter printer = new AlternatePrinter();

        Thread numbers = new Thread(() -> printer.printNumbers(5));
        Thread letters = new Thread(() -> printer.printLetters(5));

        numbers.start();
        letters.start();
        numbers.join();
        letters.join();

        assertThat(printer.getOutput())
            .containsExactly("1", "A", "2", "B", "3", "C", "4", "D", "5", "E");
    }

    @Test
    void alternation_alwaysCorrectOrder() throws InterruptedException {
        for (int trial = 0; trial < 50; trial++) {
            AlternatePrinter printer = new AlternatePrinter();
            Thread t1 = new Thread(() -> printer.printNumbers(3));
            Thread t2 = new Thread(() -> printer.printLetters(3));
            t1.start(); t2.start();
            t1.join(); t2.join();

            assertThat(printer.getOutput())
                .containsExactly("1", "A", "2", "B", "3", "C");
        }
        // 50 trials — ALWAYS correct! wait/notify guarantees order.
    }
}
